export const getGroceryProducts = (): Product[] => GROCERY_PRODUCTS;

export const getFeaturedGroceryProducts = (): Product[] => 
  GROCERY_PRODUCTS.filter(product => product.featured);

export const getGroceryProductsByBadge = (badge: string): Product[] =>
  GROCERY_PRODUCTS.filter(product => product.badge === badge);

export const getGroceryProductsByPriceRange = (min: number, max: number): Product[] =>
  GROCERY_PRODUCTS.filter(product => product.price >= min && product.price <= max);
